// Firebase initialisation. Returns true only when a real Firebase
// configuration exists (generated by `flutterfire configure`) and
// Firebase.initializeApp() succeeds. Any failure — no options file,
// no network, missing native config — is swallowed and reported as
// false, so the app falls back to local mode instead of crashing.
//
// Timeout (Nov 5, 2026 fix): on web, Firebase.initializeApp()
// dynamically imports the Firebase JS SDK from gstatic. If that
// import can never resolve (unreachable CDN, blocked network), the
// returned Future never completes and an uncaught JS promise
// rejection hangs app start forever — main() awaits this before
// runApp, so the try/catch below never runs and the app stays blank.
// A 10s timeout forces the Future to fail, so the app falls back to
// local mode and actually mounts. On a normal network init takes
// well under 10s, so the live path is unaffected.

import 'dart:async';

import 'package:firebase_core/firebase_core.dart';

import '../firebase_options.dart';

class FirebaseBackend {
  static bool configured = false;

  /// How long to wait for Firebase.initializeApp() before giving up
  /// and falling back to local mode.
  static const Duration initializeTimeout = Duration(seconds: 10);

  static Future<bool> initialize({
    Future<void> Function()? initializer,
    Duration timeout = initializeTimeout,
  }) async {
    if (!kFirebaseOptionsConfigured) return false;
    try {
      await (initializer ?? _defaultInitializer)().timeout(timeout);
      configured = true;
      return true;
    } catch (_) {
      configured = false;
      return false;
    }
  }

  static Future<void> _defaultInitializer() => Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );
}
